(() => {
    const currentIndex = chapter.index;
    const baseIndex = book.durChapterIndex;
    const indexDiff = currentIndex - baseIndex; 

    if (Math.abs(indexDiff) > 2) {
        return ''; 
    }

    const delay = Math.random() * 1400 + 100;
    Packages.java.lang.Thread.sleep(delay);

    return java.getString('[id*="content"]@html', result);
})()

